text:
In the VIBE benchmark we consider datasets whose queries are both  in-distribution  and  out-of-distribution.
The following table reports information about the size and dimensionality of each dataset, along with links that allow to download them.
db = DuckDBClient.of({
    vizdata: FileAttachment("results/data-pca-mahalanobis.parquet"),
    stats: FileAttachment("results/stats.parquet"),
  basics: {file: FileAttachment("dataset_basics.csv"), header: true},
  info: FileAttachment("results/data-info.parquet")
});
id_datasets = db.sql`select * from basics natural join info where type in ('in-distribution', 'in-distribution-additional') order by dataset`;
ood_datasets = db.sql`select * from basics natural join info where type in ('out-of-distribution', 'out-of-distribution-additional') order by dataset`;
datasets = db.sql`select * from basics natural join info where type in ('in-distribution', 'in-distribution-additional', 'out-of-distribution', 'out-of-distribution-additional') order by type, dataset`;

colors = Array.from(d3["schemeTableau10"]).toReversed();
type_colors = new Map([
  ["in-distribution", "#1f77b4"],
  ["in-distribution-additional", "#1f77b4"],
  ["out-of-distribution", "#ff7f0e"],
  ["out-of-distribution-additional", "#ff7f0e"]
])

viewof selected_dataset = Inputs.table(datasets,{
  format: {
    dataset: dataset =&gt; html`&lt;a href="https://huggingface.co/datasets/vector-index-bench/vibe/blob/main/${dataset}.hdf5"&gt;${dataset}&lt;/a&gt;`,
    type: t =&gt; html`&lt;div style="
      width: 3ex;
      height: 3ex;
      background: ${type_colors.get(t)}
    "&gt;&lt;/div&gt;`
  },
  width: {
    dataset: 280
  },
  multiple: false,
  value: datasets[0]
})
Here below we report the first two PCA components of  data  and  queries  for each dataset. Selecting a dataset in the table above allows to update the visualization.
Along with the PCA we display the distribution of Mahalanobis distances between the  data points  and the data and the  query points  and the data.
selected_data = db.sql`select * from vizdata where dataset = ${selected_dataset.dataset}`;
kde = require('fast-kde');
distances_data = db.sql`select mahalanobis_distance_to_data from vizdata where dataset = ${selected_dataset.dataset} and part = 'train'`;
density_data = kde.density1d(distances_data.map(d =&gt; d.mahalanobis_distance_to_data), { bandwidth: 3, bins: 512, pad: 4 });
distances_query = db.sql`select mahalanobis_distance_to_data from vizdata where dataset = ${selected_dataset.dataset} and part = 'test'`;
density_query = kde.density1d(distances_query.map(d =&gt; d.mahalanobis_distance_to_data), { bandwidth: 3, bins: 512, pad: 4 });

bw = 1;
density_transform = function(data, facets) {
  // Separately compute densities for each facet
  const densities = facets.map((facet) =&gt; {
    // `facet` is a `UInt32Array`, so it needs to be copied before we can use it like this
    const facetData = [...facet].map((index) =&gt; data[index]);
    const iter = (new Set(facetData.map(d =&gt; d.dataset))).values();
    const dataset = iter.next().value;
    console.log(dataset);

    // `density1d` also needs to be copied to produce (x, y) pairs for our plot
    const densityData = [
      ...kde
        .density1d(facetData, {
          x: "rc100",
          pad,
          bins,
          //extent: [0, 3]
        })
        .points("point", "density")
    ];

    densityData.forEach(d =&gt; d["dataset"] = dataset);
    return densityData;
  });

  // Simultaneously flatten the array and compute the new facets

  let newData = [];
  let newFacets = [];
  let index = 0;

  for (let density of densities) {
    let facet = [];
    for (let facetIndex = 0; facetIndex &lt; density.length; facetIndex++) {
      newData.push(density[facetIndex]);
      facet.push(index);
      index++;
    }
    newFacets.push(facet);
  }

  return {
    data: newData,
    facets: newFacets
  };
}
To characterize the difficulty of queries, and hence of the workloads associated with each dataset, we consider the relative contrast, defined as [ RC_k = ] where \(d_{avg}\) is the average distance of the query to the other points, and \(d_k\) is the distance of the query from its \(k\)-th nearest neighbor.
The plot below reports the distribution of relative contrasts for \(k=100\) for the datasets1 in the benchmark, with datasets arranged in increasing order of difficulty, top to bottom.

db = DuckDBClient.of({
  summary: FileAttachment("results/summary.parquet"),
  stats: FileAttachment("results/stats.parquet"),
  basics: {file: FileAttachment("dataset_basics.csv"), header: true},
  algorithm_basics: {file: FileAttachment("algorithms_basics.csv"), header: true}
});
k_values = db.sql`select distinct k from summary;`
dataset_catalog_rows = db.sql`
  select distinct dataset, type
  from basics natural join (select distinct dataset from summary)
`;
dataset_catalog = Array.from(dataset_catalog_rows)
  .sort((a, b) =&gt; {
    const aAdditional = a.type.endsWith("-additional");
    const bAdditional = b.type.endsWith("-additional");
    return d3.ascending(aAdditional, bAdditional) || d3.ascending(a.dataset, b.dataset);
  });
default_datasets = dataset_catalog
  .filter((d) =&gt; !d.type.endsWith("-additional"))
  .map((d) =&gt; d.dataset);
viewof recall_threshold = Inputs.range([0,1], {step: 0.01, value: 0.9, label: "minimum recall"});
viewof k_value = Inputs.select(k_values.map(d =&gt; d.k), {value: 10, label: "value of k"});
viewof selected_datasets = {
  const input = Inputs.checkbox(dataset_catalog.map((d) =&gt; d.dataset), {
    label: "datasets",
    value: default_datasets
  });
  input.classList.add("dataset-selector");
  return input;
}
selected_dataset_lookup = `|${selected_datasets.join("|")}|`;



































































fastdata = db.sql`
  with
    normalized_names as (
      select k, dataset, algorithm, params, qps, recall from summary
    ),
    selected_datasets as (
      select dataset, regexp_replace(type, '-additional$', '') as type
      from basics
      where contains(${selected_dataset_lookup}, '|' || dataset || '|')
    ),
    filtered_summary as (
      select * from normalized_names natural join selected_datasets natural left join algorithm_basics
      where not is_gpu 
    ),
    all_datasets as ( select distinct dataset, type from filtered_summary ),
    all_algorithms as ( select distinct algorithm from filtered_summary ),
    expected_combinations as (
      select *
      from all_datasets cross join all_algorithms
    ),
    ranked as (
        select *, row_number() over (partition by algorithm, dataset order by qps desc) as rank
        from filtered_summary
        where recall &gt;= ${recall_threshold} and k = ${k_value}
    ),
    scaled as (
      select
        *,
        ifnull(qps, 0) / max(qps) over (partition by dataset, type) as scaled_qps
      from ranked
        natural right join expected_combinations
    ),
    best_performing as (
      select algorithm, dataset, max(scaled_qps) as best_performance
      from scaled
      group by all
    ),
    algorithms as (
      select algorithm, avg(best_performance) as mean_perf
      from best_performing
      group by all
    ),
    algorithms_ranks as (
      select
        algorithm, mean_perf,
        row_number() over (order by mean_perf desc) as algorithm_rank
      from algorithms
    ),
    datasets as (
      select dataset, type, avg(rc100) as difficulty
      from stats natural join selected_datasets
      group by all
    ),
    dataset_ranks as (
      select
        dataset, difficulty,
        row_number() over (order by type, contains(dataset, '-ip'), difficulty desc) as dataset_rank
      from datasets 
    )
  select
    algorithm,
    regexp_replace(dataset, '-[0-9]+-(cosine|normalized|euclidean|ip)', '') as dataset,
    type as dataset_type,
    dataset_rank,
    k,
    scaled_qps,
    qps,
    params,
    (algorithm_rank / 6) as fx,
    (algorithm_rank % 6) as fy
  from scaled natural join algorithms_ranks natural join dataset_ranks
  where rank = 1 or rank is null
  order by dataset_rank, algorithm, qps;
`

facet_keys = Array.from(d3.union(fastdata.map((d) =&gt; d.algorithm)));

dataset_ranks = fastdata.reduce((map, d) =&gt; {
  map[d.dataset] = d.dataset_rank;
  return map;
}, {});
dataset_types = fastdata.reduce((map, d) =&gt; {
  map[d.dataset] = d.dataset_type;
  return map;
}, {});

longitude_domain = Object.keys(dataset_ranks).sort((a, b) =&gt; dataset_ranks[a] - dataset_ranks[b]);

// Scales
longitude = d3.scalePoint(
  longitude_domain,
  [180, -180]
).padding(0.5).align(1);
fmt_qps = d3.format(".2s");
radar_width = Math.min(width, document.querySelector(".overview-radars").clientWidth);


























































Plot.plot({
  width: radar_width,
  height: 3*radar_width/4,
  marginTop: 20,
  marginBottom: 20,
  marginLeft: 20,
  marginRight: 20,
  projection: {
    type: "azimuthal-equidistant",
    rotate: [0, -90],
    // Note: 1.22° corresponds to max. percentage (1.0), plus some room for the labels
    domain: d3.geoCircle().center([0, 90]).radius(1.22)()
  },
  facet: {
    data: fastdata,
    y: (d) =&gt; d.fx, //Math.floor(d.algorithm_rank / 4),
    x: (d) =&gt; d.fy, // d.algorithm_rank % 4,
    axis: null
  },
  fx: {padding: .1},
  fy: {padding: .1},
  marks: [
    // Facet name
    Plot.text(fastdata,
      Plot.selectFirst({
          text: "algorithm",
          frameAnchor: "top-left",
          fontWeight: "700",
          fontSize: 18
      })
    ),

    // grey discs
    Plot.geo([1.0, 0.8, 0.6, 0.4, 0.2], {
      geometry: (r) =&gt; d3.geoCircle().center([0, 90]).radius(r)(),
      stroke: "black",
      fill: "black",
      strokeOpacity: 0.2,
      fillOpacity: 0.03,
      strokeWidth: 0.5
    }),

    // colored axes
    Plot.link(longitude.domain(), {
      x1: longitude,
      y1: 90 - 1,
      x2: 0,
      y2: 90,
      stroke: d =&gt; (dataset_types[d] == "in-distribution")? "#1f77b4" : "#ff7f0e",
      strokeOpacity: 0.5,
      strokeWidth: 2.5
    }),

    // tick labels
    Plot.text([0.4, 0.6, 0.8], {
      fx: 0, fy: 0,
      x: 180,
      y: (d) =&gt; 90 - d,
      dx: 2,
      textAnchor: "start",
      text: (d) =&gt; ( d == 0.8 ? `${100 * d}%` : `${100 * d}%`),
      fill: "currentColor",
      stroke: "white",
      fontSize: 14
    }),

    // axes labels
    Plot.text(longitude.domain(), {
      fx: 0, fy: 0,
      x: longitude,
      y: 90 - 1.07,
      text: (d) =&gt; d.replaceAll("-", "\n"),
      lineWidth: 12,
      lineHeight: 1.05,
      fontSize: 12,
      fontWeight: 600
    }),

    // axes labels, initials
    Plot.text(longitude.domain(), {
      fx: 0, fy: 0, facet: "exclude",
      x: longitude,
      y: 90 - 1.09,
      text: d =&gt; d.slice(0,2),
      lineWidth: 5,
      lineHeight: 1.05,
      fontSize: 14,
      fontWeight: 600
    }),

    // areas
    Plot.area(fastdata, {
      x1: ({ dataset }) =&gt; longitude(dataset),
      y1: ({ scaled_qps }) =&gt; 90 - scaled_qps,
      x2: 0,
      y2: 90,
      fill: "gray",
      fillOpacity: 0.25,
      stroke: "gray",
      curve: "cardinal-closed"
    }),

    // data values
    Plot.dot(fastdata, {
      x: (d) =&gt; longitude(d.dataset),
      y: (d) =&gt; 90 - d.scaled_qps,
      fill: (d) =&gt; (d.dataset_type == "in-distribution")? "#1f77b4" : "#ff7f0e",
      stroke: "white"
    }),

    // interactive labels
    Plot.text(
      fastdata,
      Plot.pointer({
        x: ({ dataset }) =&gt; longitude(dataset),
        y: ({ scaled_qps }) =&gt; 90 - scaled_qps,
        text: (d) =&gt; `${fmt_qps(d.qps)} qps\n(${Math.round(100 * d.scaled_qps)}%)\n${d.params}`,
        textAnchor: "start",
        dx: 4,
        fill: "currentColor",
        stroke: "white",
        maxRadius: 10,
        fontSize: 18
      })
    )

  ]
})
